   386→    #[test]
   387→    fn test_nfd_enr_encoding() {
   388→        let spec = make_fulu_spec();
   389→        let enr = build_enr_with_config(NetworkConfig::default(), None, &spec).0;
   390→        assert_eq!(enr.next_fork_digest().unwrap(), TEST_NFD);
