    99→#[derive(Clone, PartialEq)]
   100→struct SubnetQuery {
   101→    subnet: Subnet,
   102→    min_ttl: Option<Instant>,
   103→    retries: usize,
   104→}
   105→
   106→impl SubnetQuery {
   107→    /// Returns true if this query has expired.
   108→    pub fn expired(&self) -> bool {
   109→        if let Some(ttl) = self.min_ttl {
   110→            ttl < Instant::now()
   111→        }
   112→        // `None` corresponds to long lived subnet discovery requests.
   113→        else {
   114→            false
   115→        }
   116→    }
   117→}
   118→
   119→impl std::fmt::Debug for SubnetQuery {
   120→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   121→        let min_ttl_secs = self
   122→            .min_ttl
   123→            .map(|ttl| ttl.saturating_duration_since(Instant::now()).as_secs());
   124→        f.debug_struct("SubnetQuery")
   125→            .field("subnet", &self.subnet)
   126→            .field("min_ttl_secs", &min_ttl_secs)
   127→            .field("retries", &self.retries)
   128→            .finish()
   129→    }
   130→}
   131→
   132→#[derive(Debug, Clone, PartialEq)]
   133→enum QueryType {
   134→    /// We are searching for subnet peers.
   135→    Subnet(Vec<SubnetQuery>),
   136→    /// We are searching for more peers without ENR or time constraints.
   137→    FindPeers,
   138→}
   139→
   140→/// The result of a query.
   141→struct QueryResult {
   142→    query_type: QueryType,
   143→    result: Result<Vec<Enr>, discv5::QueryError>,
   144→}
   145→
   146→// Awaiting the event stream future
   147→enum EventStream {
   148→    /// Awaiting an event stream to be generated. This is required due to the poll nature of
   149→    /// `Discovery`
   150→    Awaiting(
   151→        Pin<Box<dyn Future<Output = Result<mpsc::Receiver<discv5::Event>, discv5::Error>> + Send>>,
   152→    ),
   153→    /// The future has completed.
   154→    Present(mpsc::Receiver<discv5::Event>),
   155→    // The future has failed or discv5 has been disabled. There are no events from discv5.
   156→    InActive,
   157→}
   158→
   159→/// The main discovery service. This can be disabled via CLI arguements. When disabled the
   160→/// underlying processes are not started, but this struct still maintains our current ENR.
   161→pub struct Discovery<E: EthSpec> {
   162→    /// A collection of seen live ENRs for quick lookup and to map peer-id's to ENRs.
   163→    cached_enrs: LruCache<PeerId, Enr>,
   164→
   165→    /// The directory where the ENR is stored.
   166→    enr_dir: String,
   167→
   168→    /// The handle for the underlying discv5 Server.
   169→    ///
   170→    /// This is behind a Reference counter to allow for futures to be spawned and polled with a
   171→    /// static lifetime.
   172→    discv5: Discv5,
   173→
   174→    /// A collection of network constants that can be read from other threads.
   175→    network_globals: Arc<NetworkGlobals<E>>,
   176→
   177→    /// Indicates if we are actively searching for peers. We only allow a single FindPeers query at
   178→    /// a time, regardless of the query concurrency.
   179→    find_peer_active: bool,
   180→
   181→    /// A queue of subnet queries to be processed.
   182→    queued_queries: VecDeque<SubnetQuery>,
   183→
   184→    /// Active discovery queries.
   185→    active_queries: FuturesUnordered<std::pin::Pin<Box<dyn Future<Output = QueryResult> + Send>>>,
   186→
   187→    /// The discv5 event stream.
   188→    event_stream: EventStream,
   189→
   190→    /// Indicates if the discovery service has been started. When the service is disabled, this is
   191→    /// always false.
   192→    pub started: bool,
   193→
   194→    /// Specifies whether various port numbers should be updated after the discovery service has been started
   195→    update_ports: UpdatePorts,
   196→
   197→    spec: Arc<ChainSpec>,
   198→}
   199→
   200→impl<E: EthSpec> Discovery<E> {
   201→    /// NOTE: Creating discovery requires running within a tokio execution environment.
   202→    pub async fn new(
   203→        local_key: Keypair,
   204→        config: &NetworkConfig,
   205→        network_globals: Arc<NetworkGlobals<E>>,
   206→        spec: &ChainSpec,
   207→    ) -> Result<Self, String> {
   208→        let enr_dir = match config.network_dir.to_str() {
   209→            Some(path) => String::from(path),
   210→            None => String::from(""),
   211→        };
   212→
   213→        let local_enr = network_globals.local_enr.read().clone();
   214→        let local_node_id = local_enr.node_id();
   215→
   216→        info!(
   217→            enr = local_enr.to_base64(), seq = local_enr.seq(), id = %local_enr.node_id(),
   218→            ip4 = ?local_enr.ip4(), udp4= ?local_enr.udp4(), tcp4 = ?local_enr.tcp4(), tcp6 = ?local_enr.tcp6(), udp6 = ?local_enr.udp6(),
   219→            quic4 = ?local_enr.quic4(), quic6 = ?local_enr.quic6(),
   220→            "ENR Initialised"
   221→        );
   222→
   223→        // convert the keypair into an ENR key
   224→        let enr_key: CombinedKey = CombinedKey::from_libp2p(local_key)?;
   225→
   226→        let mut discv5 = Discv5::new(local_enr, enr_key, config.discv5_config.clone())
   227→            .map_err(|e| format!("Discv5 service failed. Error: {:?}", e))?;
   228→
   229→        // Add bootnodes to routing table
   230→        for bootnode_enr in config.boot_nodes_enr.clone() {
   231→            if bootnode_enr.node_id() == local_node_id {
   232→                // If we are a boot node, ignore adding it to the routing table
   233→                continue;
   234→            }
   235→            debug!(
   236→                node_id = %bootnode_enr.node_id(),
   237→                peer_id = %bootnode_enr.peer_id(),
   238→                ip = ?bootnode_enr.ip4(),
   239→                udp = ?bootnode_enr.udp4(),
   240→                tcp = ?bootnode_enr.tcp4(),
   241→                quic = bootnode_enr.quic4(),
   242→                "Adding node to routing table"
   243→            );
   244→            let repr = bootnode_enr.to_string();
   245→            let _ = discv5.add_enr(bootnode_enr).map_err(|e| {
   246→                error!(
   247→                    addr = repr,
   248→                    error = e.to_string(),
   249→                    "Could not add peer to the local routing table"
   250→                )
   251→            });
   252→        }
   253→
   254→        // Start the discv5 service and obtain an event stream
   255→        let event_stream = if !config.disable_discovery {
   256→            discv5.start().map_err(|e| e.to_string()).await?;
   257→            debug!("Discovery service started");
   258→            EventStream::Awaiting(Box::pin(discv5.event_stream()))
   259→        } else {
   260→            EventStream::InActive
   261→        };
   262→
   263→        if !config.boot_nodes_multiaddr.is_empty() {
   264→            info!("Contacting Multiaddr boot-nodes for their ENR");
   265→        }
   266→
   267→        // get futures for requesting the Enrs associated to these multiaddr and wait for their
   268→        // completion
   269→        let mut fut_coll = config
   270→            .boot_nodes_multiaddr
   271→            .iter()
   272→            .map(|addr| addr.to_string())
   273→            // request the ENR for this multiaddr and keep the original for logging
   274→            .map(|addr| {
   275→                futures::future::join(
   276→                    discv5.request_enr(addr.clone()),
   277→                    futures::future::ready(addr),
   278→                )
   279→            })
   280→            .collect::<FuturesUnordered<_>>();
   281→
   282→        while let Some((result, original_addr)) = fut_coll.next().await {
   283→            match result {
   284→                Ok(enr) => {
   285→                    debug!(
   286→                        node_id = %enr.node_id(),
   287→                        peer_id = %enr.peer_id(),
   288→                        ip4 = ?enr.ip4(),
   289→                        udp4 = ?enr.udp4(),
   290→                        tcp4 = ?enr.tcp4(),
   291→                        quic4 = ?enr.quic4(),
   292→                        "Adding node to routing table"
   293→                    );
   294→                    let _ = discv5.add_enr(enr).map_err(|e| {
   295→                        error!(
   296→                            addr = original_addr.to_string(),
   297→                            error = e.to_string(),
   298→                            "Could not add peer to the local routing table"
   299→                        )
   300→                    });
   301→                }
   302→                Err(e) => {
   303→                    error!(
   304→                        multiaddr = original_addr.to_string(),
   305→                        error = e.to_string(),
   306→                        "Error getting mapping to ENR"
   307→                    )
   308→                }
   309→            }
   310→        }
   311→
   312→        let update_ports = UpdatePorts {
   313→            tcp4: config.enr_tcp4_port.is_none(),
   314→            tcp6: config.enr_tcp6_port.is_none(),
   315→            quic4: config.enr_quic4_port.is_none(),
   316→            quic6: config.enr_quic6_port.is_none(),
   317→        };
   318→
   319→        Ok(Self {
   320→            cached_enrs: LruCache::new(ENR_CACHE_CAPACITY),
   321→            network_globals,
   322→            find_peer_active: false,
   323→            queued_queries: VecDeque::with_capacity(10),
   324→            active_queries: FuturesUnordered::new(),
   325→            discv5,
   326→            event_stream,
   327→            started: !config.disable_discovery,
   328→            update_ports,
   329→            enr_dir,
   330→            spec: Arc::new(spec.clone()),
   331→        })
   332→    }
   333→
   334→    /// Return the nodes local ENR.
   335→    pub fn local_enr(&self) -> Enr {
   336→        self.discv5.local_enr()
   337→    }
   338→
   339→    /// Return the cached enrs.
   340→    pub fn cached_enrs(&self) -> impl Iterator<Item = (&PeerId, &Enr)> {
   341→        self.cached_enrs.iter()
   342→    }
   343→
   344→    /// Removes a cached ENR from the list.
   345→    pub fn remove_cached_enr(&mut self, peer_id: &PeerId) -> Option<Enr> {
   346→        self.cached_enrs.pop(peer_id)
   347→    }
   348→
   349→    /// This adds a new `FindPeers` query to the queue if one doesn't already exist.
   350→    /// The `target_peers` parameter informs discovery to end the query once the target is found.
   351→    /// The maximum this can be is 16.
   352→    pub fn discover_peers(&mut self, target_peers: usize) {
   353→        // If the discv5 service isn't running or we are in the process of a query, don't bother queuing a new one.
   354→        if !self.started || self.find_peer_active {
   355→            return;
   356→        }
   357→        // Immediately start a FindNode query
   358→        let target_peers = std::cmp::min(FIND_NODE_QUERY_CLOSEST_PEERS, target_peers);
   359→        debug!(target_peers, "Starting a peer discovery request");
   360→        self.find_peer_active = true;
   361→        self.start_query(QueryType::FindPeers, target_peers, |_| true);
   362→    }
   363→
   364→    /// Processes a request to search for more peers on a subnet.
   365→    pub fn discover_subnet_peers(&mut self, subnets_to_discover: Vec<SubnetDiscovery>) {
   366→        // If the discv5 service isn't running, ignore queries
   367→        if !self.started {
   368→            return;
   369→        }
   370→        trace!(
   371→            subnets = ?subnets_to_discover.iter().map(|s| s.subnet).collect::<Vec<_>>(),
   372→            "Starting discovery query for subnets"
   373→        );
   374→        for subnet in subnets_to_discover {
   375→            self.add_subnet_query(subnet.subnet, subnet.min_ttl, 0);
   376→        }
   377→    }
   378→
   379→    /// Add an ENR to the routing table of the discovery mechanism.
   380→    pub fn add_enr(&mut self, enr: Enr) {
   381→        // add the enr to seen caches
   382→        self.cached_enrs.put(enr.peer_id(), enr.clone());
   383→
   384→        if let Err(e) = self.discv5.add_enr(enr) {
   385→            debug!(
   386→                error = %e,
   387→                "Could not add peer to the local routing table"
   388→            )
   389→        }
   390→    }
   391→
   392→    /// Returns an iterator over all enr entries in the DHT.
   393→    pub fn table_entries_enr(&self) -> Vec<Enr> {
   394→        self.discv5.table_entries_enr()
   395→    }
   396→
   397→    /// Updates the local ENR TCP port.
   398→    /// There currently isn't a case to update the address here. We opt for discovery to
   399→    /// automatically update the external address.
   400→    ///
   401→    /// If the external address needs to be modified, use `update_enr_udp_socket.
   402→    ///
   403→    /// This returns Ok(true) if the ENR was updated, otherwise Ok(false) if nothing was done.
   404→    pub fn update_enr_tcp_port(&mut self, port: u16, v6: bool) -> Result<bool, String> {
   405→        let enr_field = if v6 {
   406→            if self.discv5.external_enr().read().tcp6() == Some(port) {
   407→                // The field is already set to the same value, nothing to do
   408→                return Ok(false);
   409→            }
   410→            "tcp6"
   411→        } else {
   412→            if self.discv5.external_enr().read().tcp4() == Some(port) {
   413→                // The field is already set to the same value, nothing to do
   414→                return Ok(false);
   415→            }
   416→            "tcp"
   417→        };
   418→
   419→        self.discv5
   420→            .enr_insert(enr_field, &port)
   421→            .map_err(|e| format!("{:?}", e))?;
   422→
   423→        // replace the global version
   424→        *self.network_globals.local_enr.write() = self.discv5.local_enr();
   425→        // persist modified enr to disk
   426→        enr::save_enr_to_disk(Path::new(&self.enr_dir), &self.local_enr());
   427→        Ok(true)
   428→    }
   429→
   430→    // TODO: Group these functions here once the ENR is shared across discv5 and lighthouse and
   431→    // Lighthouse can modify the ENR directly.
   432→    // This currently doesn't support ipv6. All of these functions should be removed and
   433→    // addressed properly in the following issue.
   434→    // https://github.com/sigp/lighthouse/issues/4706
   435→    pub fn update_enr_quic_port(&mut self, port: u16, v6: bool) -> Result<bool, String> {
   436→        let enr_field = if v6 {
   437→            if self.discv5.external_enr().read().quic6() == Some(port) {
   438→                // The field is already set to the same value, nothing to do
   439→                return Ok(false);
   440→            }
   441→            "quic6"
   442→        } else {
   443→            if self.discv5.external_enr().read().quic4() == Some(port) {
   444→                // The field is already set to the same value, nothing to do
   445→                return Ok(false);
   446→            }
   447→            "quic"
   448→        };
   449→        let current_field = self.discv5.external_enr().read().quic4();
   450→        if current_field == Some(port) {
   451→            // The current field is already set, no need to update.
   452→            return Ok(false);
   453→        }
   454→
   455→        self.discv5
   456→            .enr_insert(enr_field, &port)
   457→            .map_err(|e| format!("{:?}", e))?;
   458→
   459→        // replace the global version
   460→        *self.network_globals.local_enr.write() = self.discv5.local_enr();
   461→        // persist modified enr to disk
   462→        enr::save_enr_to_disk(Path::new(&self.enr_dir), &self.local_enr());
   463→        Ok(true)
   464→    }
   465→
   466→    /// Updates the local ENR UDP socket.
   467→    ///
   468→    /// This is with caution. Discovery should automatically maintain this. This should only be
   469→    /// used when automatic discovery is disabled.
   470→    pub fn update_enr_udp_socket(&mut self, socket_addr: SocketAddr) -> Result<(), String> {
   471→        const IS_TCP: bool = false;
   472→        if self.discv5.update_local_enr_socket(socket_addr, IS_TCP) {
   473→            // persist modified enr to disk
   474→            enr::save_enr_to_disk(Path::new(&self.enr_dir), &self.local_enr());
   475→        }
   476→        *self.network_globals.local_enr.write() = self.discv5.local_enr();
   477→        Ok(())
   478→    }
   479→
   480→    pub fn update_enr_cgc(&mut self, custody_group_count: u64) -> Result<(), String> {
   481→        self.discv5
   482→            .enr_insert(PEERDAS_CUSTODY_GROUP_COUNT_ENR_KEY, &custody_group_count)
   483→            .map_err(|e| format!("{:?}", e))?;
   484→        enr::save_enr_to_disk(Path::new(&self.enr_dir), &self.local_enr());
   485→        *self.network_globals.local_enr.write() = self.discv5.local_enr();
   486→        Ok(())
   487→    }
   488→
   489→    /// Adds/Removes a subnet from the ENR attnets/syncnets Bitfield
   490→    pub fn update_enr_bitfield(&mut self, subnet: Subnet, value: bool) -> Result<(), String> {
   491→        let local_enr = self.discv5.local_enr();
   492→
   493→        match subnet {
   494→            Subnet::Attestation(id) => {
   495→                let id = *id as usize;
   496→                let mut current_bitfield = local_enr.attestation_bitfield::<E>()?;
   497→                if id >= current_bitfield.len() {
   498→                    return Err(format!(
   499→                        "Subnet id: {} is outside the ENR bitfield length: {}",
   500→                        id,
   501→                        current_bitfield.len()
   502→                    ));
   503→                }
   504→
   505→                // The bitfield is already set to required value
   506→                if current_bitfield
   507→                    .get(id)
   508→                    .map_err(|_| String::from("Subnet ID out of bounds"))?
   509→                    == value
   510→                {
   511→                    return Ok(());
   512→                }
   513→
   514→                // set the subnet bitfield in the ENR
   515→                current_bitfield.set(id, value).map_err(|_| {
   516→                    String::from("Subnet ID out of bounds, could not set subnet ID")
   517→                })?;
   518→
   519→                // insert the bitfield into the ENR record
   520→                self.discv5
   521→                    .enr_insert::<Bytes>(
   522→                        ATTESTATION_BITFIELD_ENR_KEY,
   523→                        &current_bitfield.as_ssz_bytes().into(),
   524→                    )
   525→                    .map_err(|e| format!("{:?}", e))?;
   526→            }
   527→            Subnet::SyncCommittee(id) => {
   528→                let id = *id as usize;
   529→                let mut current_bitfield = local_enr.sync_committee_bitfield::<E>()?;
   530→
   531→                if id >= current_bitfield.len() {
   532→                    return Err(format!(
   533→                        "Subnet id: {} is outside the ENR bitfield length: {}",
   534→                        id,
   535→                        current_bitfield.len()
   536→                    ));
   537→                }
   538→
   539→                // The bitfield is already set to required value
   540→                if current_bitfield
   541→                    .get(id)
   542→                    .map_err(|_| String::from("Subnet ID out of bounds"))?
   543→                    == value
   544→                {
   545→                    return Ok(());
   546→                }
   547→
   548→                // set the subnet bitfield in the ENR
   549→                current_bitfield.set(id, value).map_err(|_| {
   550→                    String::from("Subnet ID out of bounds, could not set subnet ID")
   551→                })?;
   552→
   553→                // insert the bitfield into the ENR record
   554→                self.discv5
   555→                    .enr_insert::<Bytes>(
   556→                        SYNC_COMMITTEE_BITFIELD_ENR_KEY,
   557→                        &current_bitfield.as_ssz_bytes().into(),
   558→                    )
   559→                    .map_err(|e| format!("{:?}", e))?;
   560→            }
   561→            // Data column subnets are computed from node ID. No subnet bitfield in the ENR.
   562→            Subnet::DataColumn(_) => return Ok(()),
   563→        }
   564→
   565→        // replace the global version
   566→        *self.network_globals.local_enr.write() = self.discv5.local_enr();
   567→
   568→        // persist modified enr to disk
   569→        enr::save_enr_to_disk(Path::new(&self.enr_dir), &self.local_enr());
   570→        Ok(())
   571→    }
   572→
   573→    pub fn update_enr_nfd(&mut self, nfd: [u8; 4]) -> Result<(), String> {
   574→        self.discv5
   575→            .enr_insert::<Bytes>(NEXT_FORK_DIGEST_ENR_KEY, &nfd.as_ssz_bytes().into())
   576→            .map_err(|e| format!("{:?}", e))?;
   577→        info!(
   578→            next_fork_digest = ?nfd,
   579→            "Updating the ENR nfd"
   580→        );
   581→        enr::save_enr_to_disk(Path::new(&self.enr_dir), &self.local_enr());
   582→        *self.network_globals.local_enr.write() = self.discv5.local_enr();
   583→        Ok(())
   584→    }
   585→
   586→    /// Updates the `eth2` field of our local ENR.
   587→    pub fn update_eth2_enr(&mut self, enr_fork_id: EnrForkId) {
   588→        // to avoid having a reference to the spec constant, for the logging we assume
   589→        // FAR_FUTURE_EPOCH is u64::MAX
   590→        let next_fork_epoch_log = if enr_fork_id.next_fork_epoch == u64::MAX {
   591→            String::from("No other fork")
   592→        } else {
   593→            format!("{:?}", enr_fork_id.next_fork_epoch)
   594→        };
   595→
   596→        info!(
   597→            fork_digest = ?enr_fork_id.fork_digest,
   598→            next_fork_version = ?enr_fork_id.next_fork_version,
   599→            next_fork_epoch = next_fork_epoch_log,
   600→            "Updating the ENR fork version"
   601→        );
   602→
   603→        let _ = self
   604→            .discv5
   605→            .enr_insert::<Bytes>(ETH2_ENR_KEY, &enr_fork_id.as_ssz_bytes().into())
   606→            .map_err(|e| {
   607→                warn!(
   608→                    error = ?e,
   609→                    "Could not update eth2 ENR field"
   610→                )
   611→            });
   612→
   613→        // replace the global version with discovery version
   614→        *self.network_globals.local_enr.write() = self.discv5.local_enr();
   615→
   616→        // persist modified enr to disk
   617→        enr::save_enr_to_disk(Path::new(&self.enr_dir), &self.local_enr());
   618→    }
   619→
   620→    // Bans a peer and it's associated seen IP addresses.
   621→    pub fn ban_peer(&mut self, peer_id: &PeerId, ip_addresses: Vec<IpAddr>) {
   622→        // first try and convert the peer_id to a node_id.
   623→        if let Ok(node_id) = peer_id_to_node_id(peer_id) {
   624→            // If we could convert this peer id, remove it from the DHT and ban it from discovery.
   625→            self.discv5.ban_node(&node_id, None);
   626→        }
   627→
   628→        for ip_address in ip_addresses {
   629→            self.discv5.ban_ip(ip_address, None);
   630→        }
   631→    }
   632→
   633→    /// Unbans the peer in discovery.
   634→    pub fn unban_peer(&mut self, peer_id: &PeerId, ip_addresses: Vec<IpAddr>) {
   635→        // first try and convert the peer_id to a node_id.
   636→        if let Ok(node_id) = peer_id_to_node_id(peer_id) {
   637→            self.discv5.ban_node_remove(&node_id);
   638→        }
   639→
   640→        for ip_address in ip_addresses {
   641→            self.discv5.ban_ip_remove(&ip_address);
   642→        }
   643→    }
   644→
   645→    ///  Marks node as disconnected in the DHT, freeing up space for other nodes, this also removes
   646→    ///  nodes from the cached ENR list.
   647→    pub fn disconnect_peer(&mut self, peer_id: &PeerId) {
   648→        if let Ok(node_id) = peer_id_to_node_id(peer_id) {
   649→            self.discv5.disconnect_node(&node_id);
   650→        }
   651→        // Remove the peer from the cached list, to prevent redialing disconnected
   652→        // peers.
   653→        self.cached_enrs.pop(peer_id);
   654→    }
   655→
   656→    /* Internal Functions */
   657→
   658→    /// Adds a subnet query if one doesn't exist. If a subnet query already exists, this
   659→    /// updates the min_ttl field.
   660→    fn add_subnet_query(&mut self, subnet: Subnet, min_ttl: Option<Instant>, retries: usize) {
   661→        // remove the entry and complete the query if greater than the maximum search count
   662→        if retries > MAX_DISCOVERY_RETRY {
   663→            debug!("Subnet peer discovery did not find sufficient peers. Reached max retry limit");
   664→            return;
   665→        }
   666→
   667→        // Search through any queued requests and update the timeout if a query for this subnet
   668→        // already exists
   669→        let mut found = false;
   670→        for subnet_query in self.queued_queries.iter_mut() {
   671→            if subnet_query.subnet == subnet {
   672→                if subnet_query.min_ttl < min_ttl {
   673→                    subnet_query.min_ttl = min_ttl;
   674→                }
   675→                // update the number of retries
   676→                subnet_query.retries = retries;
   677→                // mimic an `Iter::Find()` and short-circuit the loop
   678→                found = true;
   679→                break;
   680→            }
   681→        }
   682→        if !found {
   683→            // update the metrics and insert into the queue.
   684→            trace!(?subnet, retries, "Queuing subnet query");
   685→            self.queued_queries.push_back(SubnetQuery {
   686→                subnet,
   687→                min_ttl,
   688→                retries,
   689→            });
   690→            metrics::set_gauge(
   691→                &discovery_metrics::DISCOVERY_QUEUE,
   692→                self.queued_queries.len() as i64,
   693→            );
   694→        }
   695→    }
   696→
   697→    /// Consume the discovery queue and initiate queries when applicable.
   698→    ///
   699→    /// This also sanitizes the queue removing out-dated queries.
   700→    /// Returns `true` if any of the queued queries is processed and a subnet discovery
   701→    /// query is started.
   702→    fn process_queue(&mut self) -> bool {
   703→        // Sanitize the queue, removing any out-dated subnet queries
   704→        self.queued_queries.retain(|query| !query.expired());
   705→
   706→        // use this to group subnet queries together for a single discovery request
   707→        let mut subnet_queries: Vec<SubnetQuery> = Vec::new();
   708→        let mut processed = false;
   709→        // Check that we are within our query concurrency limit
   710→        while !self.at_capacity() && !self.queued_queries.is_empty() {
   711→            // consume and process the query queue
   712→            if let Some(subnet_query) = self.queued_queries.pop_front() {
   713→                subnet_queries.push(subnet_query);
   714→
   715→                // We want to start a grouped subnet query if:
   716→                //  1. We've grouped MAX_SUBNETS_IN_QUERY subnets together.
   717→                //  2. There are no more messages in the queue.
   718→                if subnet_queries.len() == MAX_SUBNETS_IN_QUERY || self.queued_queries.is_empty() {
   719→                    // This query is for searching for peers of a particular subnet
   720→                    // Drain subnet_queries so we can re-use it as we continue to process the queue
   721→                    let grouped_queries: Vec<SubnetQuery> = std::mem::take(&mut subnet_queries);
   722→                    self.start_subnet_query(grouped_queries);
   723→                    processed = true;
   724→                }
   725→            }
   726→        }
   727→        // Update the queue metric
   728→        metrics::set_gauge(
   729→            &discovery_metrics::DISCOVERY_QUEUE,
   730→            self.queued_queries.len() as i64,
   731→        );
   732→        processed
   733→    }
   734→
   735→    // Returns a boolean indicating if we are currently processing the maximum number of
   736→    // concurrent subnet queries or not.
   737→    fn at_capacity(&self) -> bool {
   738→        self.active_queries
   739→            .len()
   740→            .saturating_sub(self.find_peer_active as usize) // We only count active subnet queries
   741→            >= MAX_CONCURRENT_SUBNET_QUERIES
   742→    }
   743→
   744→    /// Runs a discovery request for a given group of subnets.
   745→    fn start_subnet_query(&mut self, subnet_queries: Vec<SubnetQuery>) {
   746→        let mut filtered_subnets: Vec<Subnet> = Vec::new();
   747→
   748→        // find subnet queries that are still necessary
   749→        let filtered_subnet_queries: Vec<SubnetQuery> = subnet_queries
   750→            .into_iter()
   751→            .filter(|subnet_query| {
   752→                // Determine if we have sufficient peers, which may make this discovery unnecessary.
   753→                let peers_on_subnet = self
   754→                    .network_globals
   755→                    .peers
   756→                    .read()
   757→                    .good_peers_on_subnet(subnet_query.subnet)
   758→                    .count();
   759→
   760→                if peers_on_subnet >= TARGET_SUBNET_PEERS {
   761→                    debug!(
   762→                        reason = "Already connected to desired peers",
   763→                        connected_peers_on_subnet = peers_on_subnet,
   764→                        target_subnet_peers = TARGET_SUBNET_PEERS,
   765→                        "Discovery ignored"
   766→                    );
   767→                    return false;
   768→                }
   769→
   770→                let target_peers = TARGET_SUBNET_PEERS.saturating_sub(peers_on_subnet);
   771→                trace!(
   772→                    ?subnet_query,
   773→                    connected_peers_on_subnet = peers_on_subnet,
   774→                    peers_to_find = target_peers,
   775→                    "Discovery query started for subnet"
   776→                );
   777→
   778→                filtered_subnets.push(subnet_query.subnet);
   779→                true
   780→            })
   781→            .collect();
   782→
   783→        // Only start a discovery query if we have a subnet to look for.
   784→        if !filtered_subnet_queries.is_empty() {
   785→            // build the subnet predicate as a combination of the eth2_fork_predicate and the subnet predicate
   786→            let subnet_predicate = subnet_predicate::<E>(filtered_subnets, self.spec.clone());
   787→
   788→            debug!(
   789→                subnets = ?filtered_subnet_queries,
   790→                "Starting grouped subnet query"
   791→            );
   792→            self.start_query(
   793→                QueryType::Subnet(filtered_subnet_queries),
   794→                TARGET_PEERS_FOR_GROUPED_QUERY,
   795→                subnet_predicate,
   796→            );
   797→        }
   798→    }
   799→
   800→    /// Search for a specified number of new peers using the underlying discovery mechanism.
   801→    ///
   802→    /// This can optionally search for peers for a given predicate. Regardless of the predicate
   803→    /// given, this will only search for peers on the same enr_fork_id as specified in the local
   804→    /// ENR.
   805→    fn start_query(
   806→        &mut self,
   807→        query: QueryType,
   808→        target_peers: usize,
   809→        additional_predicate: impl Fn(&Enr) -> bool + Send + 'static,
   810→    ) {
   811→        let enr_fork_id = match self.local_enr().eth2() {
   812→            Ok(v) => v,
   813→            Err(e) => {
   814→                crit!(error = e, "Local ENR has no fork id");
   815→                return;
   816→            }
   817→        };
   818→        // predicate for finding nodes with a matching fork and valid tcp port
   819→        let eth2_fork_predicate = move |enr: &Enr| {
   820→            // `next_fork_epoch` and `next_fork_version` can be different so that
   821→            // we can connect to peers who aren't compatible with an upcoming fork.
   822→            // `fork_digest` **must** be same.
   823→            enr.eth2().map(|e| e.fork_digest) == Ok(enr_fork_id.fork_digest)
   824→                && (enr.tcp4().is_some() || enr.tcp6().is_some())
   825→        };
   826→
   827→        // General predicate
   828→        let predicate: Box<dyn Fn(&Enr) -> bool + Send> =
   829→            Box::new(move |enr: &Enr| eth2_fork_predicate(enr) && additional_predicate(enr));
   830→
   831→        // Build the future
   832→        let query_future = self
   833→            .discv5
   834→            // Generate a random target node id.
   835→            .find_node_predicate(NodeId::random(), predicate, target_peers)
   836→            .map(|v| QueryResult {
   837→                query_type: query,
   838→                result: v,
   839→            });
   840→
   841→        // Add the future to active queries, to be executed.
   842→        self.active_queries.push(Box::pin(query_future));
   843→    }
   844→
   845→    /// Process the completed QueryResult returned from discv5.
   846→    fn process_completed_queries(
   847→        &mut self,
   848→        query: QueryResult,
   849→    ) -> Option<HashMap<Enr, Option<Instant>>> {
   850→        match query.query_type {
   851→            QueryType::FindPeers => {
   852→                self.find_peer_active = false;
   853→                match query.result {
   854→                    Ok(r) if r.is_empty() => {
   855→                        debug!("Discovery query yielded no results.");
   856→                    }
   857→                    Ok(r) => {
   858→                        debug!(peers_found = r.len(), "Discovery query completed");
   859→                        let results = r
   860→                            .into_iter()
   861→                            .map(|enr| {
   862→                                // cache the found ENR's
   863→                                self.cached_enrs.put(enr.peer_id(), enr.clone());
   864→                                (enr, None)
   865→                            })
   866→                            .collect();
   867→                        return Some(results);
   868→                    }
   869→                    Err(e) => {
   870→                        warn!(error = %e, "Discovery query failed");
   871→                    }
   872→                }
   873→            }
   874→            QueryType::Subnet(queries) => {
   875→                let subnets_searched_for: Vec<Subnet> =
   876→                    queries.iter().map(|query| query.subnet).collect();
   877→                match query.result {
   878→                    Ok(r) if r.is_empty() => {
   879→                        debug!(
   880→                            ?subnets_searched_for,
   881→                            "Grouped subnet discovery query yielded no results."
   882→                        );
   883→                        queries.iter().for_each(|query| {
   884→                            self.add_subnet_query(query.subnet, query.min_ttl, query.retries + 1);
   885→                        })
   886→                    }
   887→                    Ok(r) => {
   888→                        debug!(
   889→                            peers_found = r.len(),
   890→                            ?subnets_searched_for,
   891→                            "Peer grouped subnet discovery request completed"
   892→                        );
   893→
   894→                        let mut mapped_results = HashMap::new();
   895→
   896→                        // cache the found ENR's
   897→                        for enr in r.iter().cloned() {
   898→                            self.cached_enrs.put(enr.peer_id(), enr);
   899→                        }
   900→
   901→                        // Map each subnet query's min_ttl to the set of ENR's returned for that subnet.
   902→                        queries.iter().for_each(|query| {
   903→                            let query_str = match query.subnet {
   904→                                Subnet::Attestation(_) => "attestation",
   905→                                Subnet::SyncCommittee(_) => "sync_committee",
   906→                                Subnet::DataColumn(_) => "data_column",
   907→                            };
   908→
   909→                            if let Some(v) = metrics::get_int_counter(
   910→                                &metrics::TOTAL_SUBNET_QUERIES,
   911→                                &[query_str],
   912→                            ) {
   913→                                v.inc();
   914→                            }
   915→                            // A subnet query has completed. Add back to the queue, incrementing retries.
   916→                            self.add_subnet_query(query.subnet, query.min_ttl, query.retries + 1);
   917→
   918→                            // Check the specific subnet against the enr
   919→                            let subnet_predicate =
   920→                                subnet_predicate::<E>(vec![query.subnet], self.spec.clone());
   921→
   922→                            r.clone()
   923→                                .into_iter()
   924→                                .filter(|enr| subnet_predicate(enr))
   925→                                .for_each(|enr| {
   926→                                    if let Some(v) = metrics::get_int_counter(
   927→                                        &metrics::SUBNET_PEERS_FOUND,
   928→                                        &[query_str],
   929→                                    ) {
   930→                                        v.inc();
   931→                                    }
   932→                                    let other_min_ttl = mapped_results.get_mut(&enr);
   933→
   934→                                    // map peer IDs to the min_ttl furthest in the future
   935→                                    match (query.min_ttl, other_min_ttl) {
   936→                                        // update the mapping if the min_ttl is greater
   937→                                        (
   938→                                            Some(min_ttl_instant),
   939→                                            Some(Some(other_min_ttl_instant)),
   940→                                        ) => {
   941→                                            if min_ttl_instant
   942→                                                .saturating_duration_since(*other_min_ttl_instant)
   943→                                                > DURATION_DIFFERENCE
   944→                                            {
   945→                                                *other_min_ttl_instant = min_ttl_instant;
   946→                                            }
   947→                                        }
   948→                                        // update the mapping if we have a specified min_ttl
   949→                                        (Some(min_ttl), Some(None)) => {
   950→                                            mapped_results.insert(enr, Some(min_ttl));
   951→                                        }
   952→                                        // first seen min_ttl for this enr
   953→                                        (min_ttl, None) => {
   954→                                            mapped_results.insert(enr, min_ttl);
   955→                                        }
   956→                                        (None, Some(Some(_))) => {} // Don't replace the existing specific min_ttl
   957→                                        (None, Some(None)) => {} // No-op because this is a duplicate
   958→                                    }
   959→                                });
   960→                        });
   961→
   962→                        if mapped_results.is_empty() {
   963→                            return None;
   964→                        } else {
   965→                            return Some(mapped_results);
   966→                        }
   967→                    }
   968→                    Err(e) => {
   969→                        warn!(?subnets_searched_for, error = %e,"Grouped subnet discovery query failed");
   970→                    }
   971→                }
   972→            }
   973→        }
   974→        None
   975→    }
   976→
   977→    /// Drives the queries returning any results from completed queries.
   978→    fn poll_queries(&mut self, cx: &mut Context) -> Option<HashMap<Enr, Option<Instant>>> {
   979→        while let Poll::Ready(Some(query_result)) = self.active_queries.poll_next_unpin(cx) {
   980→            let result = self.process_completed_queries(query_result);
   981→            if result.is_some() {
   982→                return result;
   983→            }
   984→        }
   985→        None
   986→    }
   987→}
