   989→/* NetworkBehaviour Implementation */
   990→
   991→impl<E: EthSpec> NetworkBehaviour for Discovery<E> {
   992→    // Discovery is not a real NetworkBehaviour...
   993→    type ConnectionHandler = ConnectionHandler;
   994→    type ToSwarm = DiscoveredPeers;
   995→
   996→    fn handle_established_inbound_connection(
   997→        &mut self,
   998→        _connection_id: ConnectionId,
   999→        _peer: PeerId,
  1000→        _local_addr: &Multiaddr,
  1001→        _remote_addr: &Multiaddr,
  1002→    ) -> Result<libp2p::swarm::THandler<Self>, libp2p::swarm::ConnectionDenied> {
  1003→        // TODO: we might want to check discovery's banned ips here in the future.
  1004→        Ok(ConnectionHandler)
  1005→    }
  1006→
  1007→    fn handle_established_outbound_connection(
  1008→        &mut self,
  1009→        _connection_id: ConnectionId,
  1010→        _peer: PeerId,
  1011→        _addr: &Multiaddr,
  1012→        _role_override: libp2p::core::Endpoint,
  1013→        _port_use: PortUse,
  1014→    ) -> Result<libp2p::swarm::THandler<Self>, libp2p::swarm::ConnectionDenied> {
  1015→        Ok(ConnectionHandler)
  1016→    }
  1017→
  1018→    fn on_connection_handler_event(
  1019→        &mut self,
  1020→        _peer_id: PeerId,
  1021→        _connection_id: ConnectionId,
  1022→        _event: std::convert::Infallible,
  1023→    ) {
  1024→    }
  1025→
  1026→    // Main execution loop to drive the behaviour
  1027→    fn poll(&mut self, cx: &mut Context) -> Poll<ToSwarm<Self::ToSwarm, THandlerInEvent<Self>>> {
  1028→        if !self.started {
  1029→            return Poll::Pending;
  1030→        }
  1031→
  1032→        // Process the query queue
  1033→        self.process_queue();
  1034→
  1035→        // Drive the queries and return any results from completed queries
  1036→        if let Some(peers) = self.poll_queries(cx) {
  1037→            // return the result to the peer manager
  1038→            return Poll::Ready(ToSwarm::GenerateEvent(DiscoveredPeers { peers }));
  1039→        }
  1040→
  1041→        // Process the server event stream
  1042→        match self.event_stream {
  1043→            EventStream::Awaiting(ref mut fut) => {
  1044→                // Still awaiting the event stream, poll it
  1045→                if let Poll::Ready(event_stream) = fut.poll_unpin(cx) {
  1046→                    match event_stream {
  1047→                        Ok(stream) => {
  1048→                            debug!("Discv5 event stream ready");
  1049→                            self.event_stream = EventStream::Present(stream);
  1050→                        }
  1051→                        Err(e) => {
  1052→                            crit!(error = %e, "Discv5 event stream failed");
  1053→                            self.event_stream = EventStream::InActive;
  1054→                        }
  1055→                    }
  1056→                }
  1057→            }
  1058→            EventStream::InActive => {} // ignore checking the stream
  1059→            EventStream::Present(ref mut stream) => {
  1060→                while let Poll::Ready(Some(event)) = stream.poll_recv(cx) {
  1061→                    match event {
  1062→                        // We filter out unwanted discv5 events here and only propagate useful results to
  1063→                        // the peer manager.
  1064→                        discv5::Event::Discovered(_enr) => {
  1065→                            // Peers that get discovered during a query but are not contactable or
  1066→                            // don't match a predicate can end up here. For debugging purposes we
  1067→                            // log these to see if we are unnecessarily dropping discovered peers
  1068→                            /*
  1069→                            if enr.eth2() == self.local_enr().eth2() {
  1070→                                trace!( "Peer found in process of query"; "peer_id" => format!("{}", enr.peer_id()), "tcp_socket" => enr.tcp_socket());
  1071→                            } else {
  1072→                            // this is temporary warning for debugging the DHT
  1073→                            warn!( "Found peer during discovery not on correct fork"; "peer_id" => format!("{}", enr.peer_id()), "tcp_socket" => enr.tcp_socket());
  1074→                            }
  1075→                            */
  1076→                        }
  1077→                        discv5::Event::SocketUpdated(socket_addr) => {
  1078→                            info!(ip = %socket_addr.ip(), udp_port = %socket_addr.port(),"Address updated");
  1079→                            metrics::inc_counter(&metrics::ADDRESS_UPDATE_COUNT);
  1080→                            // Discv5 will have updated our local ENR. We save the updated version
  1081→                            // to disk.
  1082→
  1083→                            if (self.update_ports.tcp4 && socket_addr.is_ipv4())
  1084→                                || (self.update_ports.tcp6 && socket_addr.is_ipv6())
  1085→                            {
  1086→                                // Update the TCP port in the ENR
  1087→                                self.discv5.update_local_enr_socket(socket_addr, true);
  1088→                            }
  1089→                            let enr = self.discv5.local_enr();
  1090→                            enr::save_enr_to_disk(Path::new(&self.enr_dir), &enr);
  1091→                            // update  network globals
  1092→                            *self.network_globals.local_enr.write() = enr;
  1093→                            // A new UDP socket has been detected.
  1094→                            // NOTE: We assume libp2p itself can keep track of IP changes and we do
  1095→                            // not inform it about IP changes found via discovery.
  1096→                        }
  1097→                        _ => {} // Ignore all other discv5 server events
  1098→                    }
  1099→                }
  1100→            }
  1101→        }
  1102→        Poll::Pending
  1103→    }
  1104→
  1105→    fn on_swarm_event(&mut self, event: FromSwarm) {
  1106→        match event {
  1107→            FromSwarm::DialFailure(DialFailure { peer_id, error, .. }) => {
  1108→                self.on_dial_failure(peer_id, error)
  1109→            }
  1110→            FromSwarm::NewListenAddr(ev) => {
  1111→                let addr = ev.addr;
  1112→                let listener_id = ev.listener_id;
  1113→
  1114→                trace!(
  1115→                    ?listener_id,
  1116→                    ?addr,
  1117→                    "Received NewListenAddr event from swarm"
  1118→                );
  1119→
  1120→                let mut addr_iter = addr.iter();
  1121→
  1122→                let attempt_enr_update = match addr_iter.next() {
  1123→                    Some(Protocol::Ip4(_)) => match (addr_iter.next(), addr_iter.next()) {
  1124→                        (Some(Protocol::Tcp(port)), None) => {
  1125→                            if !self.update_ports.tcp4 {
  1126→                                debug!(multiaddr = ?addr, "Skipping ENR update");
  1127→                                return;
  1128→                            }
  1129→
  1130→                            self.update_enr_tcp_port(port, false)
  1131→                        }
  1132→                        (Some(Protocol::Udp(port)), Some(Protocol::QuicV1)) => {
  1133→                            if !self.update_ports.quic4 {
  1134→                                debug!(?addr, "Skipping ENR update");
  1135→                                return;
  1136→                            }
  1137→
  1138→                            self.update_enr_quic_port(port, false)
  1139→                        }
  1140→                        _ => {
  1141→                            debug!(
  1142→                                ?addr,
  1143→                                "Encountered unacceptable multiaddr for listening (unsupported transport)"
  1144→                            );
  1145→                            return;
  1146→                        }
  1147→                    },
  1148→                    Some(Protocol::Ip6(_)) => match (addr_iter.next(), addr_iter.next()) {
  1149→                        (Some(Protocol::Tcp(port)), None) => {
  1150→                            if !self.update_ports.tcp6 {
  1151→                                debug!(?addr, "Skipping ENR update");
  1152→                                return;
  1153→                            }
  1154→
  1155→                            self.update_enr_tcp_port(port, true)
  1156→                        }
  1157→                        (Some(Protocol::Udp(port)), Some(Protocol::QuicV1)) => {
  1158→                            if !self.update_ports.quic6 {
  1159→                                debug!(?addr, "Skipping ENR update");
  1160→                                return;
  1161→                            }
  1162→
  1163→                            self.update_enr_quic_port(port, true)
  1164→                        }
  1165→                        _ => {
  1166→                            debug!(
  1167→                                ?addr,
  1168→                                "Encountered unacceptable multiaddr for listening (unsupported transport)"
  1169→                            );
  1170→                            return;
  1171→                        }
  1172→                    },
  1173→                    _ => {
  1174→                        debug!(
  1175→                            ?addr,
  1176→                            "Encountered unacceptable multiaddr for listening (no IP)"
  1177→                        );
  1178→                        return;
  1179→                    }
  1180→                };
  1181→
  1182→                let local_enr: Enr = self.discv5.local_enr();
  1183→
  1184→                match attempt_enr_update {
  1185→                    Ok(true) => {
  1186→                        info!(enr = local_enr.to_base64(), seq = local_enr.seq(), id = %local_enr.node_id(), ip4 = ?local_enr.ip4(), udp4 = ?local_enr.udp4(), tcp4 = ?local_enr.tcp4(), tcp6 = ?local_enr.tcp6(), udp6 = ?local_enr.udp6(),"Updated local ENR")
  1187→                    }
  1188→                    Ok(false) => {} // Nothing to do, ENR already configured
  1189→                    Err(e) => warn!(error = ?e,"Failed to update ENR"),
  1190→                }
  1191→            }
  1192→            _ => {
  1193→                // Ignore events not relevant to discovery
  1194→            }
  1195→        }
  1196→    }
  1197→}
