  1199→impl<E: EthSpec> Discovery<E> {
  1200→    fn on_dial_failure(&mut self, peer_id: Option<PeerId>, error: &DialError) {
  1201→        if let Some(peer_id) = peer_id {
  1202→            match error {
  1203→                DialError::Denied { .. } => {
  1204→                    if self.network_globals.peers.read().is_connected(&peer_id) {
  1205→                        // There's an active connection, so we don’t disconnect the peer.
  1206→                        // Lighthouse dials to a peer twice using TCP and QUIC (if QUIC is not
  1207→                        // disabled). Usually, one establishes a connection, and the other fails
  1208→                        // because the peer allows only one connection per peer.
  1209→                        return;
  1210→                    }
  1211→                    // set peer as disconnected in discovery DHT
  1212→                    debug!(%peer_id, error = %ClearDialError(error),"Marking peer disconnected in DHT");
  1213→                    self.disconnect_peer(&peer_id);
  1214→                }
  1215→                DialError::LocalPeerId { .. }
  1216→                | DialError::NoAddresses
  1217→                | DialError::Transport(_)
  1218→                | DialError::WrongPeerId { .. } => {
  1219→                    // set peer as disconnected in discovery DHT
  1220→                    debug!(%peer_id, error = %ClearDialError(error),"Marking peer disconnected in DHT");
  1221→                    self.disconnect_peer(&peer_id);
  1222→                }
  1223→                DialError::DialPeerConditionFalse(_) | DialError::Aborted => {}
  1224→            }
  1225→        }
  1226→    }
  1227→}
