  1243→        let config = Arc::new(config);
  1244→        let enr_key: CombinedKey = CombinedKey::from_secp256k1(&keypair);
  1245→        let next_fork_digest = [0; 4];
  1246→        let enr: Enr = build_enr::<E>(
  1247→            &enr_key,
