  1274→    #[tokio::test]
  1275→    async fn test_add_subnet_query() {
  1276→        let mut discovery = build_discovery().await;
  1277→        let now = Instant::now();
  1278→        let mut subnet_query = SubnetQuery {
  1279→            subnet: Subnet::Attestation(SubnetId::new(1)),
  1280→            min_ttl: Some(now),
  1281→            retries: 0,
  1282→        };
  1283→        discovery.add_subnet_query(
  1284→            subnet_query.subnet,
  1285→            subnet_query.min_ttl,
  1286→            subnet_query.retries,
  1287→        );
  1288→        assert_eq!(discovery.queued_queries.back(), Some(&subnet_query));
  1289→
  1290→        // New query should replace old query
  1291→        subnet_query.min_ttl = Some(now + Duration::from_secs(1));
  1292→        discovery.add_subnet_query(subnet_query.subnet, subnet_query.min_ttl, 1);
  1293→
  1294→        subnet_query.retries += 1;
  1295→
  1296→        assert_eq!(discovery.queued_queries.len(), 1);
  1297→        assert_eq!(
  1298→            discovery.queued_queries.pop_back(),
  1299→            Some(subnet_query.clone())
  1300→        );
  1301→
  1302→        // Retries > MAX_DISCOVERY_RETRY must return immediately without adding
  1303→        // anything.
  1304→        discovery.add_subnet_query(
  1305→            subnet_query.subnet,
  1306→            subnet_query.min_ttl,
  1307→            MAX_DISCOVERY_RETRY + 1,
