  1349→        ]);
  1350→
  1351→        // Create enr which is subscribed to subnets 1 and 2
  1352→        let enr1 = make_enr(vec![1, 2]);
  1353→        let enr2 = make_enr(vec![2]);
  1354→        // Unwanted enr for the given grouped query
  1355→        let enr3 = make_enr(vec![3]);
